// v3na01_buffers_encodings / ex1 - reference solution (author only, used by `dojo verify`).

export interface Header {
  magic: string;
  version: number;
  flags: number;
  payloadLength: number;
  checksum: bigint;
}

const HEADER_SIZE = 20;
const MAGIC = "IPSK";

export function readHeader(buf: Buffer): Header {
  // Guard first: every accessor below would otherwise throw ERR_OUT_OF_RANGE,
  // which tells the caller about an offset instead of about the format.
  if (buf.length < HEADER_SIZE) {
    throw new Error(
      `readHeader: header needs ${HEADER_SIZE} bytes, got ${buf.length}`,
    );
  }

  // latin1, not ascii: ascii masks the high bit, so a corrupt magic byte would
  // be reported as a different, printable character.
  const magic = buf.toString("latin1", 0, 4);
  if (magic !== MAGIC) {
    throw new Error(`readHeader: expected magic ${MAGIC}, found ${magic}`);
  }

  return {
    magic,
    version: buf.readUInt8(4),
    flags: buf.readUInt8(5),
    // bytes 6-7 are reserved and deliberately not read
    payloadLength: buf.readUInt32BE(8),
    // 64 bits does not fit in a double; readBig* is the only correct read here
    checksum: buf.readBigUInt64LE(12),
  };
}

// v3na01_buffers_encodings / ex2 - reference solution (author only, used by `dojo verify`).

export function truncateUtf8(text: string, maxBytes: number): string {
  if (!Number.isInteger(maxBytes) || maxBytes < 0) {
    throw new Error(`truncateUtf8: maxBytes must be a non-negative integer`);
  }
  if (maxBytes === 0) return "";
  // Fast path: nothing to do if the whole string already fits.
  if (Buffer.byteLength(text, "utf8") <= maxBytes) return text;

  let used = 0;
  let endUnits = 0; // index in UTF-16 code units, for a single slice at the end

  // for...of iterates code points, so a surrogate pair arrives as one `ch`
  // and can never be split by this loop.
  for (const ch of text) {
    const cost = Buffer.byteLength(ch, "utf8");
    if (used + cost > maxBytes) break;
    used += cost;
    endUnits += ch.length; // 1 for BMP characters, 2 for a surrogate pair
  }

  return text.slice(0, endUnits);
}

// v3na01_buffers_encodings / ex3 - reference solution (author only, used by `dojo verify`).
import { StringDecoder } from "node:string_decoder";

export function decodeChunks(chunks: Buffer[]): string[] {
  // One decoder for the whole run: it buffers up to three bytes of an
  // incomplete sequence and prepends them to the next write.
  const decoder = new StringDecoder("utf8");

  // No decoder.end() call: the contract says a trailing partial sequence is
  // dropped, and end() would emit U+FFFD for it and break join("") equality.
  return chunks.map((chunk) => decoder.write(chunk));
}

// v3na01_buffers_encodings / ex4 - reference solution (author only, used by `dojo verify`).

const MAX_VARINT_BYTES = 8; // 8 * 7 = 56 bits, comfortably past 2**53

export function encodeVarint(value: number): Buffer {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new Error(
      `encodeVarint: expected a non-negative safe integer, got ${value}`,
    );
  }

  const bytes: number[] = [];
  let rest = value;
  do {
    const septet = rest % 128;
    rest = Math.floor(rest / 128); // NOT >>> 7: that truncates to 32 bits
    // Set the continuation marker only if something is still left to emit.
    bytes.push(rest > 0 ? septet | 0x80 : septet);
  } while (rest > 0);

  return Buffer.from(bytes);
}

export function decodeVarint(
  buf: Buffer,
  offset = 0,
): { value: number; bytesRead: number } {
  let value = 0;
  let shift = 0;
  let bytesRead = 0;

  for (;;) {
    if (offset + bytesRead >= buf.length) {
      throw new Error("decodeVarint: truncated varint (ran off the buffer)");
    }
    if (bytesRead >= MAX_VARINT_BYTES) {
      throw new Error(
        `decodeVarint: truncated or malformed varint (over ${MAX_VARINT_BYTES} bytes)`,
      );
    }

    const byte = buf[offset + bytesRead];
    bytesRead += 1;
    // Place value, not a shift: 2 ** shift stays exact past 2**31.
    value += (byte & 0x7f) * 2 ** shift;
    if ((byte & 0x80) === 0) break;
    shift += 7;
  }

  return { value, bytesRead };
}

// v3na01_buffers_encodings / ex5 - reference solution (author only, used by `dojo verify`).

export interface Framer {
  push(chunk: Buffer): Buffer[];
}

const HEADER = 4;

export function createFramer(maxMessageBytes = 1024 * 1024): Framer {
  let buffered = Buffer.alloc(0);

  return {
    push(chunk: Buffer): Buffer[] {
      buffered = Buffer.concat([buffered, chunk]);
      const out: Buffer[] = [];

      // `while`, not `if`: one chunk can complete several messages, and a
      // framer that returns only the first deadlocks against a waiting peer.
      for (;;) {
        if (buffered.length < HEADER) break;

        const length = buffered.readUInt32BE(0);
        // Bound the declared length BEFORE allocating or waiting on it: a
        // 4-byte header claiming 4 GiB is one packet and an OOM kill.
        if (length > maxMessageBytes) {
          throw new Error(
            `createFramer: declared message length ${length} exceeds limit ${maxMessageBytes}`,
          );
        }
        if (buffered.length < HEADER + length) break;

        out.push(buffered.subarray(HEADER, HEADER + length));
        buffered = buffered.subarray(HEADER + length);
      }

      return out;
    },
  };
}

// v3na01_buffers_encodings / ex6 - reference solution (author only, used by `dojo verify`).

export function asFloat64Array(buf: Buffer): Float64Array {
  if (buf.length % 8 !== 0) {
    throw new Error(
      `asFloat64Array: length must be a multiple of 8, got ${buf.length}`,
    );
  }

  // DataView over (buffer, byteOffset, length) — the three-argument form is
  // mandatory, because buf.buffer is the shared 8 KiB pool, not these bytes.
  // DataView also has no alignment requirement, which Float64Array does: a
  // pooled byteOffset is rarely a multiple of 8.
  const view = new DataView(buf.buffer, buf.byteOffset, buf.length);
  const out = new Float64Array(buf.length / 8);
  for (let i = 0; i < out.length; i++) {
    out[i] = view.getFloat64(i * 8, true); // true = little-endian
  }
  return out;
}

export function detach(buf: Buffer): Buffer {
  // Buffer.from(buf) copies the bytes. subarray/slice would alias them, and
  // Buffer.from(buf.buffer) would wrap the whole pool without copying at all.
  return Buffer.from(buf);
}

// v3na01_buffers_encodings / ex7 - reference solution (author only, used by `dojo verify`).
import { timingSafeEqual } from "node:crypto";

const ALPHABET = /^[A-Za-z0-9_-]*$/;

export function toBase64Url(bytes: Buffer): string {
  return bytes.toString("base64url");
}

export function fromBase64Url(text: string): Buffer {
  // Syntactic check first, purely for a decent error message.
  if (!ALPHABET.test(text)) {
    throw new Error(
      "fromBase64Url: not base64url (padding, whitespace or an out-of-alphabet character)",
    );
  }
  // 3 bytes -> 4 chars; remainders of 1 and 2 bytes -> 2 and 3 chars.
  // A length of 1 mod 4 is not the encoding of any byte string.
  if (text.length % 4 === 1) {
    throw new Error(`fromBase64Url: impossible base64url length ${text.length}`);
  }

  const bytes = Buffer.from(text, "base64url");
  // The guarantee: Node's decoder is permissive, so prove canonicity by
  // re-encoding. Two spellings of the same bytes is a signature-bypass
  // primitive wherever the string is a key and the bytes are the decision.
  if (bytes.toString("base64url") !== text) {
    throw new Error("fromBase64Url: non-canonical base64url encoding");
  }
  return bytes;
}

export function matches(a: Buffer, b: Buffer): boolean {
  // timingSafeEqual throws on a length mismatch, and length is not secret.
  if (a.length !== b.length) return false;
  return timingSafeEqual(a, b);
}

// v3na01_buffers_encodings / ex8 - reference solution (author only, used by `dojo verify`).

const isCont = (b: number): boolean => (b & 0xc0) === 0x80;

export function isValidUtf8(bytes: Buffer): boolean {
  let i = 0;

  while (i < bytes.length) {
    const b = bytes[i];

    // 1 byte: U+0000..U+007F
    if (b <= 0x7f) {
      i += 1;
      continue;
    }

    // 2 bytes: U+0080..U+07FF.
    // Starts at 0xc2, not 0xc0: c0/c1 could only encode < U+0080, i.e. an
    // overlong, so they are rejected by the lead byte alone.
    if (b >= 0xc2 && b <= 0xdf) {
      if (i + 1 >= bytes.length || !isCont(bytes[i + 1])) return false;
      i += 2;
      continue;
    }

    // 3 bytes: U+0800..U+FFFF, minus the surrogates.
    if (b >= 0xe0 && b <= 0xef) {
      if (i + 2 >= bytes.length) return false;
      const b1 = bytes[i + 1];
      // e0: second byte must be >= a0, or the value would be < U+0800 (overlong)
      // ed: second byte must be <= 9f, or the value lands in U+D800..U+DFFF
      const lo = b === 0xe0 ? 0xa0 : 0x80;
      const hi = b === 0xed ? 0x9f : 0xbf;
      if (b1 < lo || b1 > hi) return false;
      if (!isCont(bytes[i + 2])) return false;
      i += 3;
      continue;
    }

    // 4 bytes: U+10000..U+10FFFF. f5..ff would all exceed U+10FFFF.
    if (b >= 0xf0 && b <= 0xf4) {
      if (i + 3 >= bytes.length) return false;
      const b1 = bytes[i + 1];
      // f0: second byte >= 90, else < U+10000 (overlong)
      // f4: second byte <= 8f, else > U+10FFFF
      const lo = b === 0xf0 ? 0x90 : 0x80;
      const hi = b === 0xf4 ? 0x8f : 0xbf;
      if (b1 < lo || b1 > hi) return false;
      if (!isCont(bytes[i + 2]) || !isCont(bytes[i + 3])) return false;
      i += 4;
      continue;
    }

    // 0x80..0xc1 (stray continuation or overlong lead) and 0xf5..0xff.
    return false;
  }

  return true;
}

exercises.importantHints:
## Hint 1

The decoder's shape is the thing to decide first, and there is only one that
does not become a mess: a single mutable `offset` threaded through small
readers.

```ts
let offset = 0;
const readVarint = (): number => {
  const { value, bytesRead } = decodeVarint(buf, offset);
  offset += bytesRead;
  return value;
};
const readBytes = (n: number): Buffer => {
  if (offset + n > buf.length) throw new Error("decodeRecord: truncated");
  const out = buf.subarray(offset, offset + n);
  offset += n;
  return out;
};
```

Every read advances the cursor and every read bounds-checks. Once those two
helpers exist, the field loop is a `switch` and about twenty lines.

## Hint 2

Type dispatch on the encode side is where the subtle bugs live. `typeof 7n` is
`"bigint"`, not `"number"`. `Buffer.isBuffer(x)` must be checked before any
object test, because a `Buffer` is also a `Uint8Array` and also an object.
And the split between tag `0x01` and `0x02` is `Number.isSafeInteger(v) &&
v >= 0` — note that `-0`, `NaN` and `Infinity` all fall to the float64 branch,
which round-trips them correctly, except `-0`, which comes back as `-0` and
compares equal to `0` under `===` but not under `Object.is`. Decide what your
gate should expect and say so in a comment.

## Hint 3

Shape: `encodeRecord` builds a `Buffer[]` and concatenates once; a private
`encodeValue(value): Buffer[]` returning the tag plus payload keeps the field
loop short. `decodeRecord` uses the cursor helpers, loops the field count,
reads name and tag, `switch`es on the tag, and finishes with
`if (offset !== buf.length) throw`. The decision left to you is whether
`decodeVarint` is imported from ex4 or reimplemented — the gate runs your file
in isolation, so it must be self-contained; copy it in, and notice how much of
protocol work is exactly this kind of vendoring.

references.solution.ts:
// v3na01_buffers_encodings / challenge - reference solution (author only, used by `dojo verify`).

export type Value = number | bigint | string | boolean | Buffer;

const TAG_UINT = 0x01;
const TAG_FLOAT = 0x02;
const TAG_STRING = 0x03;
const TAG_BYTES = 0x04;
const TAG_BOOL = 0x05;
const TAG_BIGINT = 0x06;

const MAX_VARINT_BYTES = 8;

// Self-contained copies of ex4: the gate runs this file in isolation.
function encodeVarint(value: number): Buffer {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new Error(`encodeVarint: expected a non-negative safe integer`);
  }
  const bytes: number[] = [];
  let rest = value;
  do {
    const septet = rest % 128;
    rest = Math.floor(rest / 128);
    bytes.push(rest > 0 ? septet | 0x80 : septet);
  } while (rest > 0);
  return Buffer.from(bytes);
}

function decodeVarintAt(
  buf: Buffer,
  offset: number,
): { value: number; bytesRead: number } {
  let value = 0;
  let shift = 0;
  let bytesRead = 0;
  for (;;) {
    if (offset + bytesRead >= buf.length || bytesRead >= MAX_VARINT_BYTES) {
      throw new Error("decodeRecord: truncated varint");
    }
    const byte = buf[offset + bytesRead];
    bytesRead += 1;
    value += (byte & 0x7f) * 2 ** shift;
    if ((byte & 0x80) === 0) break;
    shift += 7;
  }
  return { value, bytesRead };
}

function encodeValue(value: Value): Buffer[] {
  // bigint before number: typeof 7n is "bigint", and the two must not merge.
  if (typeof value === "bigint") {
    const b = Buffer.alloc(8);
    b.writeBigInt64LE(value, 0);
    return [Buffer.from([TAG_BIGINT]), b];
  }
  if (typeof value === "boolean") {
    return [Buffer.from([TAG_BOOL, value ? 1 : 0])];
  }
  if (typeof value === "number") {
    if (Number.isSafeInteger(value) && value >= 0) {
      return [Buffer.from([TAG_UINT]), encodeVarint(value)];
    }
    const b = Buffer.alloc(8);
    b.writeDoubleLE(value, 0);
    return [Buffer.from([TAG_FLOAT]), b];
  }
  if (typeof value === "string") {
    const bytes = Buffer.from(value, "utf8");
    return [Buffer.from([TAG_STRING]), encodeVarint(bytes.length), bytes];
  }
  // Buffer check last, but before any generic object handling.
  if (Buffer.isBuffer(value)) {
    return [Buffer.from([TAG_BYTES]), encodeVarint(value.length), value];
  }
  throw new Error(`encodeRecord: unsupported value type ${typeof value}`);
}

export function encodeRecord(record: Record<string, Value>): Buffer {
  const entries = Object.entries(record);
  const parts: Buffer[] = [encodeVarint(entries.length)];

  for (const [name, value] of entries) {
    const nameBytes = Buffer.from(name, "utf8");
    // byteLength, never name.length: they differ for any non-ASCII name and
    // the decoder would desynchronise for the rest of the record.
    parts.push(encodeVarint(nameBytes.length), nameBytes, ...encodeValue(value));
  }

  // One concat at the end: concatenating per field is O(n^2) bytes copied.
  return Buffer.concat(parts);
}

export function decodeRecord(buf: Buffer): Record<string, Value> {
  let offset = 0;

  const readVarint = (): number => {
    const { value, bytesRead } = decodeVarintAt(buf, offset);
    offset += bytesRead;
    return value;
  };
  const readBytes = (n: number): Buffer => {
    if (offset + n > buf.length) throw new Error("decodeRecord: truncated record");
    const out = buf.subarray(offset, offset + n);
    offset += n;
    return out;
  };
  const readByte = (): number => readBytes(1)[0];

  const count = readVarint();
  const out: Record<string, Value> = {};

  for (let i = 0; i < count; i++) {
    const nameBytes = readBytes(readVarint());
    const name = new TextDecoder("utf-8", { fatal: true }).decode(nameBytes);
    const tag = readByte();

    switch (tag) {
      case TAG_UINT:
        out[name] = readVarint();
        break;
      case TAG_FLOAT:
        out[name] = readBytes(8).readDoubleLE(0);
        break;
      case TAG_STRING:
        out[name] = new TextDecoder("utf-8", { fatal: true }).decode(
          readBytes(readVarint()),
        );
        break;
      case TAG_BYTES:
        // Copy: the returned buffer must not alias the caller's input.
        out[name] = Buffer.from(readBytes(readVarint()));
        break;
      case TAG_BOOL: {
        const b = readByte();
        if (b > 1) throw new Error(`decodeRecord: invalid boolean byte ${b}`);
        out[name] = b === 1;
        break;
      }
      case TAG_BIGINT:
        out[name] = readBytes(8).readBigInt64LE(0);
        break;
      default:
        throw new Error(`decodeRecord: unknown type tag 0x${tag.toString(16)}`);
    }
  }

  // Trailing bytes are an error: without this, a valid record with an
  // attacker's suffix decodes exactly like the original.
  if (offset !== buf.length) {
    throw new Error(
      `decodeRecord: ${buf.length - offset} trailing byte(s) after the last field`,
    );
  }
  return out;
}

// v3na01_buffers_encodings / review1 - reference solution (author only, used by `dojo verify`).

export function hexdump(buf: Buffer, width = 16): string {
  if (!Number.isInteger(width) || width <= 0) {
    throw new Error(`hexdump: width must be a positive integer, got ${width}`);
  }

  // Each byte is 2 hex digits plus a separator, minus the trailing separator.
  const hexColumn = width * 3 - 1;
  const lines: string[] = [];

  // i < buf.length, so a length that is an exact multiple of width does not
  // produce a trailing empty line, and an empty buffer produces no lines.
  for (let i = 0; i < buf.length; i += width) {
    const slice = buf.subarray(i, i + width); // subarray clamps at the end

    const hex = [...slice]
      .map((b) => b.toString(16).padStart(2, "0")) // 0x0a must print as "0a"
      .join(" ")
      .padEnd(hexColumn, " ");

    // Range test on the byte, not a decoded string: "ascii" would mask the
    // high bit and print 0xe9 as "i", and "utf8" would emit U+FFFD.
    const text = [...slice]
      .map((b) => (b >= 0x20 && b <= 0x7e ? String.fromCharCode(b) : "."))
      .join("");

    lines.push(`${i.toString(16).padStart(8, "0")}: ${hex} |${text}|`);
  }

  return lines.join("\n");
}

exercises.hints:
## Hint 1

The critical fact is what `read(4)` does when only three bytes are buffered: it
returns `null` and leaves the three bytes alone. It does not short-read and it
does not mean the stream is finished. So `null` is not a terminal condition —
it is "come back after the next `readable` event". Which means your handler is
allowed to do nothing at all, quite often.

## Hint 2

The listener triangle, sketched on a simpler problem — waiting for the first
chunk of any size:

```ts
return new Promise<Buffer>((resolve, reject) => {
  const onReadable = () => { const c = src.read(); if (c) finish(null, c); };
  const onEnd = () => finish(new Error("empty stream"));
  const onError = (e: Error) => finish(e);
  const finish = (err: Error | null, value?: Buffer) => {
    src.off("readable", onReadable);
    src.off("end", onEnd);
    src.off("error", onError);
    err ? reject(err) : resolve(value!);
  };
  src.on("readable", onReadable).on("end", onEnd).on("error", onError);
});
```

Three listeners, one `finish` that removes all three. Adapt the middle line.


## Hint 3

Shape: a zero guard, then one promise holding three listeners and a single
`settle` that detaches all three. Call your `readable` handler once manually
after attaching, because a stream handed to you may already have bytes buffered
and will not emit another `readable` until somebody asks. The decision left to
you is whether that manual first call is necessary or merely defensive — trace
what happens when `readExactly` is called twice in a row on the same stream and
you will find out.

references.solution.ts:
// v3na02_readable_writable / ex1 - reference solution (author only, used by `dojo verify`).
import type { Readable } from "node:stream";

export function readExactly(readable: Readable, n: number): Promise<Buffer> {
  if (!Number.isInteger(n) || n < 0) {
    throw new Error(`readExactly: n must be a non-negative integer, got ${n}`);
  }
  if (n === 0) return Promise.resolve(Buffer.alloc(0));

  return new Promise<Buffer>((resolve, reject) => {
    const settle = (err: Error | null, value?: Buffer): void => {
      // Detach everything on every path: a leftover listener on a long-lived
      // stream retains this closure and its buffer forever.
      readable.off("readable", onReadable);
      readable.off("end", onEnd);
      readable.off("error", onError);
      if (err) reject(err);
      else resolve(value as Buffer);
    };

    const onReadable = (): void => {
      // read(n) is all-or-nothing: null means "not enough yet", never "done".
      const chunk = readable.read(n) as Buffer | null;
      if (chunk !== null) settle(null, chunk);
    };

    const onEnd = (): void => {
      // The stream is finished, so whatever remains is all there will ever be.
      const rest = (readable.read() as Buffer | null) ?? Buffer.alloc(0);
      settle(
        new Error(`readExactly: needed ${n} bytes, stream ended with ${rest.length}`),
      );
    };

    const onError = (err: Error): void => settle(err);

    readable.on("readable", onReadable);
    readable.on("end", onEnd);
    readable.on("error", onError);

    // The stream may already have data buffered from a previous consumer, in
    // which case no further 'readable' will fire until we ask.
    onReadable();
  });
}

// v3na02_readable_writable / ex2 - reference solution (author only, used by `dojo verify`).
import type { Readable } from "node:stream";

export function sniff(readable: Readable, n: number): Promise<Buffer> {
  if (!Number.isInteger(n) || n < 0) {
    throw new Error(`sniff: n must be a non-negative integer, got ${n}`);
  }
  if (n === 0) return Promise.resolve(Buffer.alloc(0));

  return new Promise<Buffer>((resolve, reject) => {
    const settle = (err: Error | null, value?: Buffer): void => {
      readable.off("readable", onReadable);
      readable.off("end", onEnd);
      readable.off("error", onError);
      if (err) reject(err);
      else resolve(value as Buffer);
    };

    const give = (prefix: Buffer): void => {
      // Never unshift an empty buffer, and never after 'end': the second
      // throws ERR_STREAM_UNSHIFT_AFTER_END_EVENT.
      if (prefix.length > 0 && !readable.readableEnded) readable.unshift(prefix);
      // Hand back a copy: unshift returned the *same* object to the stream's
      // internal buffer, and a caller that mutates it would corrupt the stream.
      settle(null, Buffer.from(prefix));
    };

    const onReadable = (): void => {
      const chunk = readable.read(n) as Buffer | null;
      if (chunk !== null) give(chunk);
    };

    const onEnd = (): void => {
      // Short stream: take whatever is left, which may be nothing at all.
      const rest = (readable.read() as Buffer | null) ?? Buffer.alloc(0);
      // The stream has ended, so this prefix cannot be given back; the
      // contract is that a short stream returns what exists.
      settle(null, Buffer.from(rest));
    };

    const onError = (err: Error): void => settle(err);

    readable.on("readable", onReadable);
    readable.on("end", onEnd);
    readable.on("error", onError);
    onReadable();
  });
}

exercises.hints:
## Hint 1

Everything in this exercise is a question about *when*. Constructing a stream
must do nothing. Reading must acquire. Ending — by any route — must release,
once. Node gives you a hook for each of those three moments; the only one that
might be new is the first, and it was added precisely because people were
opening files in constructors.

## Hint 2

The hook signatures, on a made-up resource:

```ts
new Readable({
  objectMode: true,
  construct(callback) {
    acquire().then((h) => { handle = h; callback(); }, callback);
  },
  read() { /* handle is guaranteed to exist here */ },
  destroy(err, callback) {
    if (!handle) return callback(err);
    handle.release().then(() => callback(err), () => callback(err));
  },
});
```

Two details to copy: `callback(err)` from `construct` fails the stream before
any read happens, and `destroy` passes its *incoming* error onward rather than
replacing it.


## Hint 3

Shape: one `let resource` in the closure and three hooks referring to it —
`construct` assigning it, `read` using it, `destroy` releasing it and setting
it back to `undefined` so a second call cannot double-close. The decision left
to you is the `highWaterMark`. The object-mode default is 16, which means the
machinery will call `_read` until sixteen items are buffered — for a resource
whose `next()` is an expensive round trip, that is fifteen calls the consumer
never asked for.

references.solution.ts:
// v3na02_readable_writable / ex3 - reference solution (author only, used by `dojo verify`).
import { Readable } from "node:stream";

export interface Resource<T> {
  next(): Promise<T | null>;
  close(): Promise<void>;
}

export function createLazySource<T>(open: () => Promise<Resource<T>>): Readable {
  let resource: Resource<T> | undefined;

  return new Readable({
    objectMode: true,
    highWaterMark: 1, // one item of demand at a time: no read-ahead

    // Acquisition happens here, not in this function's body, so constructing
    // the stream costs nothing and holds nothing.
    construct(callback) {
      open().then(
        (r) => {
          resource = r;
          callback();
        },
        // callback(err) errors the stream before any _read runs, and leaves
        // `resource` undefined so _destroy knows there is nothing to close.
        (err) => callback(err as Error),
      );
    },

    read() {
      resource!.next().then(
        (value) => {
          this.push(value === null ? null : value);
        },
        (err) => {
          // destroy(), not push(): exactly one terminal action per read.
          this.destroy(err as Error);
        },
      );
    },

    // The single teardown path: runs exactly once for normal end (autoDestroy),
    // explicit destroy, a read error, or a consumer breaking out of for-await.
    destroy(err, callback) {
      if (!resource) return callback(err);
      const r = resource;
      resource = undefined; // makes a double close impossible
      r.close().then(
        () => callback(err),
        // The incoming error wins: a close failure is usually a consequence.
        (closeErr) => callback(err ?? (closeErr as Error)),
      );
    },
  });
}

