// v3na02_readable_writable / ex4 - reference solution (author only, used by `dojo verify`).
import { Writable } from "node:stream";

export interface BatchSink {
  writable: Writable;
  batches(): Buffer[][];
  finalised(): boolean;
}

export function createBatchSink(): BatchSink {
  const batches: Buffer[][] = [];
  let finalised = false;

  const writable = new Writable({
    // Required even though writev exists: Node only calls writev when more
    // than one write is buffered. A lone write() + end() goes here, and a
    // sink without it throws ERR_METHOD_NOT_IMPLEMENTED at runtime.
    write(chunk: Buffer, _encoding, callback) {
      batches.push([chunk]);
      callback();
    },

    // chunks is Array<{ chunk, encoding }> — the elements are wrappers.
    writev(chunks, callback) {
      batches.push(chunks.map((c) => c.chunk as Buffer));
      callback();
    },

    // Runs after end() and after every buffered write has been handed over;
    // 'finish' fires when this callback does.
    final(callback) {
      finalised = true;
      callback();
    },
  });

  return {
    writable,
    batches: () => batches,
    finalised: () => finalised,
  };
}

// v3na02_readable_writable / ex5 - reference solution (author only, used by `dojo verify`).
import type { Readable, Writable } from "node:stream";

type AnyStream = (Readable | Writable) & {
  errored?: Error | null;
  destroyed?: boolean;
  writableEnded?: boolean;
  writableFinished?: boolean;
  readableEnded?: boolean;
  writable?: boolean;
  readable?: boolean;
};

const destroyedEarly = (): Error =>
  new Error("settled: stream was destroyed before completing");

export function settled(stream: Readable | Writable): Promise<"finished"> {
  const s = stream as AnyStream;

  // --- synchronous prelude: the state may already be terminal, and events
  // are never replayed. Most specific first: an errored stream is also
  // destroyed, so checking `destroyed` first would report failures as clean.
  if (s.errored) return Promise.reject(s.errored);
  if (s.writableFinished || s.readableEnded) return Promise.resolve("finished");
  if (s.destroyed) return Promise.reject(destroyedEarly());

  return new Promise<"finished">((resolve, reject) => {
    const settle = (err: Error | null): void => {
      stream.off("finish", onFinish);
      stream.off("end", onFinish);
      stream.off("close", onClose);
      stream.off("error", onError);
      if (err) reject(err);
      else resolve("finished");
    };

    let done = false;
    const onFinish = (): void => {
      done = true;
      settle(null);
    };
    // 'close' arrives for both good and bad endings; it only decides the
    // outcome when neither 'finish'/'end' nor 'error' got there first.
    const onClose = (): void => {
      if (done) return;
      settle(s.errored ?? destroyedEarly());
    };
    const onError = (err: Error): void => settle(err);

    stream.on("finish", onFinish);
    stream.on("end", onFinish);
    stream.on("close", onClose);
    stream.on("error", onError);
  });
}

