## Hint 1

There is an impedance mismatch here and it cannot be removed, only managed. The
source produces whenever it likes; the stream accepts only when asked. Between
them you need a buffer *you* control — because if you let the stream's internal
buffer absorb everything, you have a queue whose growth you cannot see and
cannot bound.

## Hint 2

The pause flag, sketched:

```ts
let paused = false;
const emit = (value: T) => {
  if (paused) { queue.push(value); return; }
  if (!this.push(value)) paused = true;
};
// and in _read:
read() {
  paused = false;
  while (!paused && queue.length > 0) {
    if (!this.push(queue.shift()!)) paused = true;
  }
}
```

Note that `_read` drains the queue *before* anything else, and that a `push`
during the drain can pause you again mid-loop. Also note `queue.shift()` is
O(n) on a large array — fine here, worth an index cursor in anger.


## Hint 3

Shape: closure state of `queue`, `paused`, `ended`, `unsubscribe`; a `drain()`
helper that pushes from the queue until `push` says stop and then pushes
`null` if the source has ended and the queue is empty; `_read` that subscribes
on first call, clears `paused` and drains; `_destroy` that unsubscribes once.
The decision left to you is what `drain()` does when the source has ended and
the queue is empty *twice* — `push(null)` a second time is an error, so
something has to remember.

references.solution.ts:
// v3na02_readable_writable / ex6 - reference solution (author only, used by `dojo verify`).
import { Readable } from "node:stream";

export type Emit<T> = (value: T) => void;
export type Subscribe<T> = (
  emit: Emit<T>,
  end: () => void,
  fail: (err: Error) => void,
) => () => void;

export function createPushSource<T>(subscribe: Subscribe<T>): Readable {
  const queue: T[] = [];
  let paused = false;
  let ended = false;
  let finishedPushing = false;
  let unsubscribe: (() => void) | undefined;

  const stream: Readable = new Readable({
    objectMode: true,

    read() {
      // Subscribe lazily, on the first demand rather than at construction.
      if (!unsubscribe) {
        unsubscribe = subscribe(
          (value) => {
            if (ended) return; // a misbehaving source must not crash us
            // Once push() says false, everything goes to our own queue, which
            // we can see and bound - unlike the stream's internal buffer.
            if (paused) {
              queue.push(value);
              return;
            }
            if (!stream.push(value)) paused = true;
          },
          () => {
            // Do NOT push(null) here: the queue may still hold values, and
            // ending now would truncate the stream under load only.
            ended = true;
            if (!paused) drain();
          },
          (err) => stream.destroy(err),
        );
      }

      paused = false;
      drain();
    },

    destroy(err, callback) {
      // Exactly once, on every ending: normal end, early destroy, or failure.
      const un = unsubscribe;
      unsubscribe = () => {}; // keep it truthy so _read never resubscribes
      un?.();
      callback(err);
    },
  });

  function drain(): void {
    while (!paused && queue.length > 0) {
      if (!stream.push(queue.shift() as T)) paused = true;
    }
    if (ended && !finishedPushing && queue.length === 0) {
      finishedPushing = true;
      stream.push(null);
    }
  }

  return stream;
}

// v3na02_readable_writable / ex7 - reference solution (author only, used by `dojo verify`).
import { finished } from "node:stream";
import type { Readable } from "node:stream";

function toError(reason: unknown): Error {
  if (reason instanceof Error) return reason;
  // No AbortError class exists in Node's public API; the cross-platform
  // convention is an Error whose `name` is exactly "AbortError".
  const err = new Error("The operation was aborted");
  err.name = "AbortError";
  return err;
}

export function withAbort<T extends Readable>(stream: T, signal: AbortSignal): T {
  // A listener on an already-fired signal never runs, so cancelling before we
  // start would otherwise be the one case that silently does nothing.
  if (signal.aborted) {
    stream.destroy(toError(signal.reason));
    return stream;
  }

  const onAbort = (): void => {
    if (stream.destroyed || stream.readableEnded) return;
    stream.destroy(toError(signal.reason));
  };

  signal.addEventListener("abort", onAbort, { once: true });

  // finished() fires for every ending - end, error, destroy - and returns its
  // own cleanup function, which must be called or it is a second leak.
  const cleanupFinished = finished(stream, () => {
    signal.removeEventListener("abort", onAbort);
    cleanupFinished();
  });

  return stream;
}

// v3na02_readable_writable / ex8 - reference solution (author only, used by `dojo verify`).
import { Readable } from "node:stream";

interface Branch {
  stream: Readable;
  live: boolean;
  wants: boolean;
}

export function tee(source: Readable): [Readable, Readable] {
  const branches: Branch[] = [];
  let wake: (() => void) | null = null;
  let pumping = false;

  // Resolves as soon as some live branch calls _read.
  const demand = (): Promise<void> =>
    new Promise<void>((resolve) => {
      wake = resolve;
    });

  const nudge = (): void => {
    const w = wake;
    wake = null;
    w?.();
  };

  const makeBranch = (): Branch => {
    const branch: Branch = { stream: null as unknown as Readable, live: true, wants: false };
    branch.stream = new Readable({
      objectMode: true,
      highWaterMark: 8,
      read() {
        branch.wants = true;
        nudge();
        void pump();
      },
      destroy(err, callback) {
        branch.live = false;
        // Only when *both* branches are gone does the source stop.
        if (branches.every((b) => !b.live)) source.destroy();
        nudge();
        callback(err);
      },
    });
    return branch;
  };

  branches.push(makeBranch(), makeBranch());

  async function pump(): Promise<void> {
    if (pumping) return;
    pumping = true;
    try {
      for await (const item of source) {
        const live = branches.filter((b) => b.live);
        if (live.length === 0) break;

        for (const b of live) {
          // push() returning false is the branch saying "full": clear its
          // demand flag so the pump waits for its next _read.
          if (!b.stream.push(item)) b.wants = false;
        }

        // Wait only when nobody wants more; one hungry branch keeps us moving,
        // and the other's items sit in its own stream buffer.
        while (branches.some((b) => b.live) && !branches.some((b) => b.live && b.wants)) {
          await demand();
        }
      }
      for (const b of branches) if (b.live) b.stream.push(null);
    } catch (err) {
      for (const b of branches) if (b.live) b.stream.destroy(err as Error);
    } finally {
      pumping = false;
    }
  }

  return [branches[0].stream, branches[1].stream];
}

