## Challenge — a frame reader driven by read(n)

Edit `challenge/solution.ts`. Implement:

```ts
export function createFrameReader(
  bytes: Readable,
  maxFrameBytes?: number,
): Readable;
```

Turn a byte Readable carrying `uint32be`-length-prefixed messages into an
object-mode Readable of message `Buffer`s. `maxFrameBytes` defaults to
`1024 * 1024`.

The constraint that makes this the challenge: **drive it with the
`readable`/`read(n)` protocol**, not by accumulating a leftover buffer and
slicing it. Ask for four bytes; when you have them, ask for exactly that many
more. `unshift` is available if you need to give bytes back.

```ts
const wire = Readable.from([
  Buffer.from("00000002", "hex"), Buffer.from("6869", "hex"),
  Buffer.from("000000036162", "hex"), Buffer.from("63", "hex"),
]);
await toArray(createFrameReader(wire));
// [<Buffer 68 69>, <Buffer 61 62 63>]
```

Required behaviour:

- a zero-length frame yields an empty buffer and is not skipped;
- a source that ends cleanly on a frame boundary ends the output normally;
- a source that ends mid-frame destroys the output with an `Error` mentioning
  `incomplete frame`;
- a declared length above `maxFrameBytes` destroys the output with an `Error`
  mentioning the limit, checked before any read of that size;
- destroying the output destroys the source;
- the output must not read ahead: with a `highWaterMark` of 1, the gate asserts
  that no more than two frames' worth of source bytes have been consumed while
  the consumer holds at the first frame.

```
uv run dojo test node v3na02_readable_writable challenge
```

references.solution.ts:
// v3na02_readable_writable / challenge - reference solution (author only, used by `dojo verify`).
import { Readable } from "node:stream";
import { once } from "node:events";

const HEADER = 4;

// Await exactly n bytes. Returns null if the source ended first.
async function readN(src: Readable, n: number): Promise<Buffer | null> {
  if (n === 0) return Buffer.alloc(0);
  for (;;) {
    const chunk = src.read(n) as Buffer | null;
    if (chunk !== null) return chunk;
    if (src.readableEnded) return null;
    // once() rejects if the source errors, so failures propagate without a
    // separate 'error' listener here.
    await once(src, "readable");
  }
}

export function createFrameReader(
  bytes: Readable,
  maxFrameBytes = 1024 * 1024,
): Readable {
  let reading = false;

  const out = new Readable({
    objectMode: true,
    highWaterMark: 1, // no read-ahead: one frame of demand at a time

    read() {
      if (reading) return;
      reading = true;

      void (async () => {
        try {
          const header = await readN(bytes, HEADER);
          if (header === null) {
            // Ended on a frame boundary: a clean end.
            out.push(null);
            return;
          }

          const length = header.readUInt32BE(0);
          // Bound before reading: a 4-byte header can otherwise ask us to
          // buffer gigabytes on the strength of one packet.
          if (length > maxFrameBytes) {
            out.destroy(
              new Error(
                `createFrameReader: frame length ${length} exceeds limit ${maxFrameBytes}`,
              ),
            );
            return;
          }

          const payload = await readN(bytes, length);
          if (payload === null) {
            // Ended mid-frame: corruption, not completion.
            out.destroy(
              new Error(
                `createFrameReader: incomplete frame, wanted ${length} payload bytes`,
              ),
            );
            return;
          }

          out.push(payload);
        } catch (err) {
          out.destroy(err as Error);
        } finally {
          reading = false;
        }
      })();
    },

    destroy(err, callback) {
      bytes.destroy();
      callback(err);
    },
  });

  return out;
}

