```

references.solution.ts:
// v3na02_readable_writable / review1 - reference solution (author only, used by `dojo verify`).
import type { Readable, Writable } from "node:stream";

export type StreamState =
  | "errored"
  | "destroyed"
  | "ended"
  | "ending"
  | "flowing"
  | "paused"
  | "idle";

type AnyStream = {
  errored?: Error | null;
  destroyed?: boolean;
  writableFinished?: boolean;
  writableEnded?: boolean;
  readableEnded?: boolean;
  readableFlowing?: boolean | null;
};

export function describeStream(stream: Readable | Writable): StreamState {
  const s = stream as AnyStream;

  // Most specific first. An errored stream is also destroyed and closed, so
  // testing `destroyed` earlier would report every failure as a clean stop.
  if (s.errored) return "errored";
  if (s.destroyed) return "destroyed";

  // Finished: everything written has flushed, or the readable half is done.
  if (s.writableFinished === true || s.readableEnded === true) return "ended";

  // end() called but _final has not completed yet.
  if (s.writableEnded === true) return "ending";

  if ("readableFlowing" in stream) {
    // Strict comparisons: null is falsy, and collapsing it into "paused" would
    // hide the state where nobody has ever read - an open resource doing
    // nothing, which is a leak rather than a pause.
    if (s.readableFlowing === true) return "flowing";
    if (s.readableFlowing === false) return "paused";
    return "idle";
  }

  return "idle";
}

// v3na03_transform_objectmode / ex1 - reference solution (author only, used by `dojo verify`).
import { Transform } from "node:stream";
import { StringDecoder } from "node:string_decoder";

export function createLineSplitter(): Transform {
  const decoder = new StringDecoder("utf8");
  let remainder = "";

  return new Transform({
    writableObjectMode: false, // bytes in
    readableObjectMode: true, // strings out

    transform(chunk: Buffer, _encoding, callback) {
      // One decoder for the stream: it holds back an incomplete multi-byte
      // sequence rather than turning it into two U+FFFDs.
      const parts = (remainder + decoder.write(chunk)).split("\n");
      // The last element is whatever followed the final "\n" - the
      // maybe-line. Only the end of the stream can say if it is a line.
      remainder = parts.pop() as string;
      for (const line of parts) {
        // Strip a "\r" that belonged to a "\r\n" pair. Doing it per line
        // survives a "\r\n" that was itself split across two chunks, because
        // the "\r" is already in `remainder` by then.
        this.push(line.endsWith("\r") ? line.slice(0, -1) : line);
      }
      callback();
    },

    flush(callback) {
      remainder += decoder.end();
      // Guarded: an unconditional push gives every newline-terminated file a
      // trailing empty line, and no push loses the last record of a file
      // that has no final newline.
      if (remainder.length > 0) {
        this.push(remainder.endsWith("\r") ? remainder.slice(0, -1) : remainder);
      }
      callback();
    },
  });
}

