references.solution.ts:
// v3na03_transform_objectmode / ex2 - reference solution (author only, used by `dojo verify`).
import { Transform } from "node:stream";

export function createBatcher<T>(size: number): Transform {
  // Fail at wiring time with a clean stack, not mid-stream at 3am.
  if (!Number.isInteger(size) || size < 1) {
    throw new Error(`createBatcher: size must be a positive integer, got ${size}`);
  }

  let batch: T[] = [];

  return new Transform({
    objectMode: true,
    // Items out are `size` times bigger than items in; the default of 16 on
    // both sides means 16 + 16*size items resident at steady state.
    readableHighWaterMark: 1,

    transform(item: T, _encoding, callback) {
      batch.push(item);
      if (batch.length === size) {
        this.push(batch);
        batch = []; // a NEW array: length = 0 would empty the one just emitted
      }
      callback();
    },

    flush(callback) {
      // Guarded: an unconditional push turns every idle stream into a
      // zero-row insert downstream.
      if (batch.length > 0) this.push(batch);
      callback();
    },
  });
}

// v3na03_transform_objectmode / ex3 - reference solution (author only, used by `dojo verify`).
import { Transform } from "node:stream";

export function createNdjsonSerialiser(): Transform {
  return new Transform({
    writableObjectMode: true, // objects in
    readableObjectMode: false, // bytes out - explicitly, so piping to a file works

    transform(value: unknown, _encoding, callback) {
      let json: string | undefined;
      try {
        json = JSON.stringify(value);
      } catch (err) {
        // Circular references and bigints throw. Fail this write; do not
        // throw out of _transform, which would escape into the machinery.
        callback(err as Error);
        return;
      }

      // undefined, functions and symbols do NOT throw - they return undefined.
      if (json === undefined) {
        callback(
          new Error(`createNdjsonSerialiser: value is not serialisable (${typeof value})`),
        );
        return;
      }

      // Terminator, not separator: two serialised streams concatenate cleanly.
      callback(null, Buffer.from(`${json}\n`, "utf8"));
    },
  });
}

