## Problem 4 — zero out, sometimes

Edit `ex4/solution.ts`. Implement:

```ts
export function createAsyncFilter<T>(
  predicate: (item: T) => Promise<boolean>,
): Transform;
```

An object-mode Transform that keeps items whose predicate resolves `true`,
drops the rest, and destroys the stream with the predicate's error when it
rejects.

```ts
const evens = createAsyncFilter<number>(async (n) => n % 2 === 0);
// in:  1, 2, 3, 4  →  out: 2, 4

const bad = createAsyncFilter<number>(async (n) => {
  if (n === 3) throw new Error("boom");
  return true;
});
// in: 1, 2, 3, 4 → emits 1, 2, then the pipeline rejects with "boom",
//                  and the predicate is never called with 4.
```

Requirements the gate checks: the callback is called exactly once per item
(`ERR_MULTIPLE_CALLBACK` fails the run); items are emitted in input order; the
predicate is never called concurrently — it sees one item at a time; and a
rejected predicate produces the original error object, not a wrapper.

```
uv run dojo test node v3na03_transform_objectmode ex4
```

references.solution.ts:
// v3na03_transform_objectmode / ex4 - reference solution (author only, used by `dojo verify`).
import { Transform } from "node:stream";

export function createAsyncFilter<T>(
  predicate: (item: T) => Promise<boolean>,
): Transform {
  return new Transform({
    objectMode: true,

    // Callback style, not `async transform`: the async form makes the returned
    // promise a second completion signal, and mixing the two either stalls the
    // stream or produces an unhandled rejection on the reject path.
    transform(item: T, _encoding, callback) {
      predicate(item).then(
        (keep) => {
          if (keep) this.push(item);
          // Exactly one callback per outcome - keep and drop share this line.
          callback();
        },
        // The original error, unwrapped: callers branch on `code`, `name` and
        // `instanceof`, and a wrapper destroys all three.
        (err) => callback(err as Error),
      );
    },
  });
}

