```

references.solution.ts:
// v3na03_transform_objectmode / ex7 - reference solution (author only, used by `dojo verify`).
import { PassThrough, compose } from "node:stream";
import type { Duplex } from "node:stream";

export type Stage<I, O> = (source: AsyncIterable<I>) => AsyncIterable<O>;

export function composeStages(stages: Stage<any, any>[]): Duplex {
  // compose() with no arguments throws, so the identity case is explicit.
  if (stages.length === 0) return new PassThrough({ objectMode: true });

  // Each stage receives the whole upstream as an async iterable and yields as
  // many outputs as it likes: the ratio problems and _flush disappear, and a
  // `throw` inside a stage destroys the composed Duplex.
  return compose(...(stages as Parameters<typeof compose>)) as Duplex;
}

