## Problem 8 — concurrency without reordering

Edit `ex8/solution.ts`. Implement:

```ts
export function createConcurrentMap<I, O>(
  fn: (item: I) => Promise<O>,
  concurrency: number,
): Transform;
```

An object-mode Transform running up to `concurrency` mappings at once and
emitting results in **input order**.

```ts
const map = createConcurrentMap(async (n: number) => {
  await delay(n === 1 ? 50 : 0);      // the first item is the slowest
  return n * 10;
}, 4);
// in:  1, 2, 3, 4
// out: 10, 20, 30, 40      — in order, despite 1 finishing last
```

Requirements the gate checks:

- at most `concurrency` calls to `fn` are outstanding at any moment, measured
  by an entry/exit counter inside the gate's `fn`;
- with `concurrency` of 4 and four 50 ms items, the whole thing takes about
  50 ms, not 200 — measured by counting overlapping calls, not by a clock;
- output order equals input order;
- the first rejection destroys the stream with that error and no further calls
  to `fn` are made;
- results still pending when the input ends are all emitted before the stream
  finishes.

```
uv run dojo test node v3na03_transform_objectmode ex8
```

references.solution.ts:
// v3na03_transform_objectmode / ex8 - reference solution (author only, used by `dojo verify`).
import { Transform } from "node:stream";

interface Slot<O> {
  done: boolean;
  value?: O;
  error?: Error;
  promise: Promise<void>;
}

export function createConcurrentMap<I, O>(
  fn: (item: I) => Promise<O>,
  concurrency: number,
): Transform {
  if (!Number.isInteger(concurrency) || concurrency < 1) {
    throw new Error(
      `createConcurrentMap: concurrency must be a positive integer, got ${concurrency}`,
    );
  }

  const pending: Slot<O>[] = [];
  let failed: Error | undefined;

  const stream = new Transform({
    objectMode: true,

    transform(item: I, _encoding, callback) {
      if (failed) {
        callback(failed);
        return;
      }

      const slot: Slot<O> = { done: false, promise: Promise.resolve() };
      // Attach the handlers immediately: a promise that rejects with nothing
      // attached triggers unhandledRejection, which is fatal by default, and
      // these sit in the queue for many turns of the loop.
      slot.promise = fn(item).then(
        (value) => {
          slot.value = value;
          slot.done = true;
        },
        (err) => {
          slot.error = err as Error;
          slot.done = true;
        },
      );
      pending.push(slot);

      drain();

      if (pending.length < concurrency) {
        // Room for another: accept the next item immediately.
        callback();
      } else {
        // Window full: wait for the OLDEST to settle, which is also the next
        // one we are allowed to emit.
        pending[0].promise.then(() => {
          drain();
          callback(failed);
        });
      }
    },

    flush(callback) {
      // Everything still in flight must be emitted before the readable side
      // ends - there may be up to `concurrency - 1` results outstanding.
      Promise.all(pending.map((s) => s.promise)).then(() => {
        drain();
        callback(failed);
      });
    },
  });

  // Push strictly from the head: a settled item behind an unsettled one waits,
  // which is the head-of-line blocking that ordering costs.
  function drain(): void {
    while (pending.length > 0 && pending[0].done) {
      const slot = pending.shift() as Slot<O>;
      if (slot.error) {
        failed ??= slot.error;
        stream.destroy(slot.error);
        return;
      }
      stream.push(slot.value as O);
    }
  }

  return stream;
}

