## Challenge — parse, enrich, batch

Edit `challenge/solution.ts`. Implement:

```ts
export interface EnrichingBatcherOptions<T, U> {
  enrich: (row: T) => Promise<U>;
  batchSize: number;
  concurrency: number;
  onBadLine?: (line: string, error: Error) => void;   // absent = fail the stream
}

export function createEnrichingBatcher<T, U>(
  options: EnrichingBatcherOptions<T, U>,
): Duplex;
```

One Duplex: NDJSON **bytes** in, arrays of enriched objects out. Three stages
in sequence — split into lines and parse, enrich with bounded concurrency in
input order, batch into arrays of `batchSize`.

```ts
const stage = createEnrichingBatcher<{ id: number }, { id: number; ok: boolean }>({
  enrich: async (row) => ({ ...row, ok: true }),
  batchSize: 2,
  concurrency: 4,
});

await pipeline(
  Readable.from(['{"id":1}\n{"id":2}\n{"id":3}\n']),
  stage,
  sink,
);
// sink sees: [{id:1,ok:true}, {id:2,ok:true}], [{id:3,ok:true}]
```

Required behaviour:

- blank lines are skipped, not parsed;
- a malformed line with no `onBadLine` destroys the Duplex with a `SyntaxError`
  whose message names the offending line number;
- with `onBadLine`, the callback is invoked and the line is skipped;
- input not ending in a newline still yields its final record;
- enrichment errors destroy the Duplex with the original error;
- the final partial batch is emitted, and it waits for in-flight enrichment —
  the gate ends the input while three mappings are outstanding and requires all
  three in the last batch;
- an empty input produces no batches at all.

```
uv run dojo test node v3na03_transform_objectmode challenge
```

exercises.hints:
## Hint 1

Build it as three separate stages and compose them. Each one is an exercise you
have already done — ex1's splitter, ex8's ordered concurrent map, ex2's batcher
— and the value of doing it this way is that each stage's end-of-input
behaviour is independent, which is exactly the part that goes wrong when you
try to write it as one Transform with one `_flush`.

## Hint 2

As generators the three stages are short, and their `_flush` equivalents are
just the statements after their loops:

```ts
async function* parse(source: AsyncIterable<Buffer>) {
  let rest = "", lineNo = 0;
  for await (const chunk of source) {
    const parts = (rest + chunk.toString("utf8")).split("\n");
    rest = parts.pop()!;
    for (const line of parts) { lineNo++; /* skip blank, parse, yield */ }
  }
  if (rest.trim()) { lineNo++; /* the same handling, once more */ }
}
```

Notice the duplication between the loop body and the trailing case — factor it
into a local function before it becomes two divergent copies of the bad-line
policy.

## Hint 3

Shape: three generator stages plus `compose(parse, enrich, batch)`. The enrich
stage is the one that cannot be a plain `for await ... yield await fn(x)`,
because that is serial; it needs ex8's window, expressed here as an array of
promises you push onto and shift from. The decision left to you is where
`batchSize` and `concurrency` are validated. Doing it in the factory before any
generator is constructed is the version whose stack trace names your caller.

references.solution.ts:
// v3na03_transform_objectmode / challenge - reference solution (author only, used by `dojo verify`).
import { compose } from "node:stream";
import type { Duplex } from "node:stream";

export interface EnrichingBatcherOptions<T, U> {
  enrich: (row: T) => Promise<U>;
  batchSize: number;
  concurrency: number;
  onBadLine?: (line: string, error: Error) => void;
}

export function createEnrichingBatcher<T, U>(
  options: EnrichingBatcherOptions<T, U>,
): Duplex {
  const { enrich, batchSize, concurrency, onBadLine } = options;

  // Validate in the factory: the stack trace then names the caller, not a
  // generator resumed from deep inside the stream machinery.
  if (!Number.isInteger(batchSize) || batchSize < 1) {
    throw new Error(`createEnrichingBatcher: batchSize must be a positive integer`);
  }
  if (!Number.isInteger(concurrency) || concurrency < 1) {
    throw new Error(`createEnrichingBatcher: concurrency must be a positive integer`);
  }

  async function* parse(source: AsyncIterable<Buffer>): AsyncIterable<T> {
    let rest = "";
    let lineNo = 0;
    const handle = function* (line: string): Generator<T> {
      lineNo += 1;
      if (line.trim() === "") return; // blank lines are skipped, not parsed
      try {
        yield JSON.parse(line) as T;
      } catch (err) {
        const wrapped = new SyntaxError(
          `createEnrichingBatcher: malformed JSON on line ${lineNo}: ${(err as Error).message}`,
        );
        if (!onBadLine) throw wrapped;
        onBadLine(line, wrapped);
      }
    };

    for await (const chunk of source) {
      const parts = (rest + chunk.toString("utf8")).split("\n");
      rest = parts.pop() as string;
      for (const line of parts) yield* handle(line);
    }
    // Input with no trailing newline still has a final record.
    if (rest.length > 0) yield* handle(rest);
  }

  async function* enrichStage(source: AsyncIterable<T>): AsyncIterable<U> {
    const pending: Promise<U>[] = [];
    for await (const row of source) {
      const p = enrich(row);
      p.catch(() => {}); // queued promises must not look unhandled
      pending.push(p);
      // Emit strictly from the head, so output order is input order.
      while (pending.length >= concurrency) yield await (pending.shift() as Promise<U>);
    }
    while (pending.length > 0) yield await (pending.shift() as Promise<U>);
  }

  async function* batch(source: AsyncIterable<U>): AsyncIterable<U[]> {
    let current: U[] = [];
    for await (const item of source) {
      current.push(item);
      if (current.length === batchSize) {
        yield current;
        current = []; // a fresh array: the consumer holds the old one
      }
    }
    // The trailing partial batch. This runs only after enrichStage has
    // drained its own queue, so nothing in flight is lost.
    if (current.length > 0) yield current;
  }

  return compose(parse, enrichStage, batch) as Duplex;
}

// v3na03_transform_objectmode / review1 - reference solution (author only, used by `dojo verify`).
import { Transform } from "node:stream";

export function createSplitter(separator: Buffer | string): Transform {
  const sep = Buffer.isBuffer(separator) ? separator : Buffer.from(separator, "utf8");
  if (sep.length === 0) {
    throw new Error("createSplitter: separator must not be empty");
  }

  // The whole unmatched tail, not "everything after the last separator": a
  // multi-byte separator can straddle a chunk boundary, and those bytes are
  // not after any separator.
  let buffered = Buffer.alloc(0);

  let sawInput = false;

  return new Transform({
    writableObjectMode: false, // bytes in
    // Objects out, even though every item is a Buffer: byte mode silently
    // drops a zero-length push, and an empty field between two separators
    // must survive.
    readableObjectMode: true,

    transform(chunk: Buffer, _encoding, callback) {
      sawInput = true;
      buffered = Buffer.concat([buffered, chunk]);

      let from = 0;
      for (;;) {
        // Search the JOINED buffer, so a separator spanning the seam is found.
        const at = buffered.indexOf(sep, from);
        if (at === -1) break;
        this.push(buffered.subarray(from, at));
        from = at + sep.length;
      }
      buffered = buffered.subarray(from);
      callback();
    },

    flush(callback) {
      // "a|" is two fields, the second empty - so the trailing segment is
      // pushed even when it is zero-length. Only a stream that never received
      // a byte emits nothing at all.
      if (sawInput) this.push(buffered);
      callback();
    },
  });
}

