## Problem 1 — the contract by hand

Edit `ex1/solution.ts`. Implement:

```ts
export function writeAll(
  writable: Writable,
  chunks: Iterable<Buffer | string>,
): Promise<number>;
```

Write every chunk in order, honouring backpressure, then `end()` the stream and
resolve with **the number of times you had to wait for `drain`**.

```ts
const sink = new Writable({ highWaterMark: 4, write(_c, _e, cb) { setImmediate(cb); } });
await writeAll(sink, [Buffer.alloc(4), Buffer.alloc(4), Buffer.alloc(4)]);
// 2 or 3 — every write past the first fills the 4-byte mark
```

Requirements:

- resolve only after the stream has finished, not merely after `end()` returns;
- if the stream fails at any point — including **while you are waiting for
  `drain`** — reject with that error rather than hanging;
- an empty iterable still ends the stream and resolves with `0`;
- never call `end()` twice.

The gate runs a sink that fails on the fourth chunk while the pump is parked
waiting to drain, and requires a rejection within a few event-loop turns.

```
uv run dojo test node v3na04_backpressure_pipeline ex1
```

references.solution.ts:
// v3na04_backpressure_pipeline / ex1 - reference solution (author only, used by `dojo verify`).
import { once } from "node:events";
import { finished } from "node:stream/promises";
import type { Writable } from "node:stream";

export async function writeAll(
  writable: Writable,
  chunks: Iterable<Buffer | string>,
): Promise<number> {
  let waits = 0;

  for (const chunk of chunks) {
    // write() always accepts the chunk; the boolean is advice about the buffer.
    if (!writable.write(chunk)) {
      waits += 1;
      // once() from node:events rejects if the stream errors while we wait -
      // a hand-rolled `new Promise(res => w.once("drain", res))` would hang
      // forever, because a dead stream never drains.
      await once(writable, "drain");
    }
  }

  writable.end();
  // finished() waits for the stream to close its resources, which 'finish'
  // does not; it also rejects on a late error.
  await finished(writable);

  return waits;
}

// v3na04_backpressure_pipeline / ex2 - reference solution (author only, used by `dojo verify`).
import { pipeline } from "node:stream/promises";
import type { Readable, Writable } from "node:stream";

export function transfer(source: Readable, destination: Writable): Promise<void> {
  // pipeline, not pipe. pipe() relays data and backpressure only: on a
  // destination error it unpipes and leaves the source open and flowing,
  // holding its file descriptor or socket for the life of the process.
  //
  // The promise form (node:stream/promises), not the callback form of the
  // same name from node:stream - awaiting that one resolves immediately with
  // the destination stream and transfers nothing.
  return pipeline(source, destination);
}

// v3na04_backpressure_pipeline / ex3 - reference solution (author only, used by `dojo verify`).
import { pipeline } from "node:stream/promises";
import type { Duplex, Readable, Writable } from "node:stream";

function asAbortError(err: unknown): Error {
  const out = new Error("runWithTimeout: the operation was aborted", { cause: err });
  out.name = "AbortError";
  return out;
}

export async function runWithTimeout(
  streams: [Readable, ...Duplex[], Writable],
  ms: number,
): Promise<void> {
  try {
    // The signal goes on the pipeline, not on any one stream: only the chain
    // knows about every stage, and destroying one leaves the others waiting.
    // AbortSignal.timeout unrefs its timer, so a fast chain still exits.
    await pipeline(streams as unknown as Parameters<typeof pipeline>, {
      signal: AbortSignal.timeout(ms),
    });
  } catch (err) {
    // AbortSignal.timeout rejects with a TimeoutError; the contract here is an
    // AbortError. cause keeps the original so a caller can still tell a
    // deadline from a manual cancel.
    if ((err as Error)?.name === "TimeoutError" || (err as Error)?.name === "AbortError") {
      throw asAbortError(err);
    }
    throw err;
  }
}

