// v3na04_backpressure_pipeline / ex4 - reference solution (author only, used by `dojo verify`).
import { Transform } from "node:stream";

export interface TokenBucketOptions {
  capacity: number;
  perTick: number;
  onTick: (refill: () => void) => void;
}

export function createTokenBucket(options: TokenBucketOptions): Transform {
  const { capacity, perTick, onTick } = options;
  if (capacity < 1 || perTick < 1) {
    throw new Error("createTokenBucket: capacity and perTick must be >= 1");
  }

  let tokens = capacity; // starts full
  // At most one chunk is ever parked: the machinery does not deliver another
  // until our callback fires, which is the whole throttling mechanism.
  let parked: { cost: number; release: () => void } | null = null;

  const tryRelease = (): void => {
    if (parked && tokens >= parked.cost) {
      const { cost, release } = parked;
      parked = null;
      tokens -= cost;
      release();
    }
  };

  onTick(() => {
    tokens = Math.min(capacity, tokens + perTick);
    tryRelease();
  });

  return new Transform({
    transform(chunk: Buffer, _encoding, callback) {
      // A chunk bigger than the bucket can never reach `tokens >= chunk.length`,
      // so the requirement is capped at capacity - otherwise one large chunk
      // deadlocks the stream forever.
      const cost = Math.min(chunk.length, capacity);

      if (tokens >= cost) {
        tokens -= cost;
        callback(null, chunk);
        return;
      }

      // Not enough: hold the callback. The writable buffer fills, write()
      // upstream returns false, and the producer stops - for free.
      parked = { cost, release: () => callback(null, chunk) };
    },

    flush(callback) {
      // A parked chunk at end() must still be released, or the last chunk is
      // dropped exactly when nobody is watching.
      if (!parked) {
        callback();
        return;
      }
      const previous = parked.release;
      parked = { cost: parked.cost, release: () => { previous(); callback(); } };
      tryRelease();
    },
  });
}

