// v3na04_backpressure_pipeline / ex5 - reference solution (author only, used by `dojo verify`).
import { once } from "node:events";
import { finished } from "node:stream/promises";
import type { Readable, Writable } from "node:stream";

export interface PressureReport {
  drains: number;
  maxBuffered: number;
  chunks: number;
  bytes: number;
}

export async function observePressure(
  source: Readable,
  sink: Writable,
): Promise<PressureReport> {
  let drains = 0;
  let maxBuffered = 0;
  let chunks = 0;
  let bytes = 0;

  const onDrain = (): void => {
    drains += 1;
  };
  sink.on("drain", onDrain);

  try {
    for await (const chunk of source) {
      const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk));
      chunks += 1;
      bytes += buf.length;

      const ok = sink.write(buf);
      // Sample HERE: after the write, before any await. One statement later
      // and every sample comes from an already-drained buffer.
      if (sink.writableLength > maxBuffered) maxBuffered = sink.writableLength;

      if (!ok) await once(sink, "drain");
    }
    sink.end();
    await finished(sink);
  } finally {
    // The sink may outlive this call; a per-transfer listener left behind is
    // the standard emitter leak.
    sink.off("drain", onDrain);
  }

  // maxBuffered can exceed the high-water mark by up to one chunk: write()
  // accepts the chunk and only then reports that the buffer is over the mark.
  return { drains, maxBuffered, chunks, bytes };
}

