// v3na04_backpressure_pipeline / ex6 - reference solution (author only, used by `dojo verify`).
import { Readable } from "node:stream";

export interface BoundedBridge<T> {
  stream: Readable;
  push(item: T): Promise<void>;
  end(): void;
  fail(err: Error): void;
  parked(): number;
}

export function createBoundedBridge<T>(limit: number): BoundedBridge<T> {
  if (!Number.isInteger(limit) || limit < 1) {
    throw new Error(`createBoundedBridge: limit must be a positive integer`);
  }

  const queue: T[] = [];
  const waiters: Array<{ resolve: () => void; reject: (err: Error) => void }> = [];
  let ended = false;
  let finishedPushing = false;
  let wantsMore = false; // the consumer asked and we had nothing to give
  let parkedCount = 0;

  const stream = new Readable({
    objectMode: true,
    highWaterMark: limit,
    read() {
      wantsMore = true;
      deliver();
    },
  });

  function deliver(): void {
    while (wantsMore && queue.length > 0) {
      const item = queue.shift() as T;
      // One item left the queue, so exactly one parked producer may proceed.
      waiters.shift()?.resolve();
      if (!stream.push(item)) wantsMore = false;
    }
    if (ended && !finishedPushing && queue.length === 0) {
      finishedPushing = true;
      stream.push(null);
    }
  }

  return {
    stream,

    push(item: T): Promise<void> {
      if (ended) return Promise.reject(new Error("createBoundedBridge: push after end"));
      queue.push(item);
      deliver();
      if (queue.length < limit) return Promise.resolve();
      parkedCount += 1;
      // The promise IS the backpressure: a producer that awaits it runs at
      // the consumer's rate.
      return new Promise<void>((resolve, reject) => waiters.push({ resolve, reject }));
    },

    end(): void {
      ended = true;
      // Not push(null) here: the queue may still hold items the consumer has
      // not taken, and ending now would truncate them silently.
      deliver();
    },

    fail(err: Error): void {
      ended = true;
      // Copy before iterating: rejecting mutates nothing here, but the
      // handlers may re-enter and push again.
      const pending = waiters.splice(0, waiters.length);
      for (const w of pending) w.reject(err);
      stream.destroy(err);
    },

    parked: () => parkedCount,
  };
}

// v3na04_backpressure_pipeline / ex7 - reference solution (author only, used by `dojo verify`).
import { Readable } from "node:stream";

export interface LazySource {
  stream: Readable;
  produced(): number;
}

export function createLazySource<T>(
  items: readonly T[],
  highWaterMark: number,
): LazySource {
  let produced = 0;

  // The counter lives inside the generator: it is the only place that knows
  // what was actually yielded, as opposed to what was consumed.
  async function* generate(): AsyncGenerator<T> {
    for (const item of items) {
      produced += 1;
      yield item;
    }
  }

  // highWaterMark: 0 does NOT mean "produce nothing until asked". push()
  // always returns false at 0, but the machinery still primes the stream with
  // one _read, so exactly one item is produced before anyone reads. A mark of
  // 1 is what "one item of lookahead" actually means.
  const stream = Readable.from(generate(), { objectMode: true, highWaterMark });

  return { stream, produced: () => produced };
}

