// v3na04_backpressure_pipeline / ex8 - reference solution (author only, used by `dojo verify`).
import { finished } from "node:stream";
import type { Duplex, Readable, Writable } from "node:stream";

type AnyStream = Readable | Writable | Duplex;

export function myPipeline(
  ...streams: [Readable, ...(Duplex | Writable)[]]
): Promise<void> {
  if (streams.length < 2) {
    throw new Error("myPipeline: need at least a source and a destination");
  }

  return new Promise<void>((resolve, reject) => {
    const all = streams as unknown as AnyStream[];
    const last = all[all.length - 1];

    let firstError: Error | undefined;
    let settled = false;
    const cleanups: Array<() => void> = [];

    const settle = (): void => {
      if (settled) return;
      settled = true;
      for (const c of cleanups) c();
      if (firstError) reject(firstError);
      else resolve();
    };

    const failAll = (err: Error, culprit: AnyStream): void => {
      // The first error wins: a transform failing destroys itself, which makes
      // the source's pipe report ERR_STREAM_DESTROYED and the sink report a
      // premature close. Three errors, one cause.
      firstError ??= err;
      for (const s of all) {
        // Destroy without an argument: passing `err` to every stage produces a
        // cascade of duplicate rejections from streams that did nothing wrong.
        if (s !== culprit && !s.destroyed) s.destroy();
      }
    };

    for (const stream of all) {
      cleanups.push(
        // finished() fires for end, finish, error and destroy, and synthesises
        // ERR_STREAM_PREMATURE_CLOSE for a stream destroyed without completing.
        finished(stream, (err) => {
          if (err) failAll(err, stream);
          // Resolve only when the LAST stage is done - 'finish' would fire
          // before a file sink has closed its descriptor.
          if (stream === last || firstError) settle();
        }),
      );
    }

    // Wiring is the easy half: one reduce. Backpressure comes along for free.
    all.reduce((a, b) => (a as Readable).pipe(b as Writable) as unknown as AnyStream);
  });
}

