// v3na04_backpressure_pipeline / challenge - reference solution (author only, used by `dojo verify`).
import { Readable, Transform } from "node:stream";
import { pipeline } from "node:stream/promises";
import type { Writable } from "node:stream";

export interface IngestOptions {
  limit: number;
  signal?: AbortSignal;
}

export interface IngestReport {
  received: number;
  written: number;
  parked: number;
}

export type Subscription = { unsubscribe(): void };

export type Subscribe<T> = (handlers: {
  onItem: (item: T) => void | Promise<void>;
  onEnd: () => void;
  onError: (err: Error) => void;
}) => Subscription;

function abortError(reason: unknown): Error {
  if (reason instanceof Error) return reason;
  const err = new Error("runIngest: the operation was aborted");
  err.name = "AbortError";
  return err;
}

export async function runIngest<T>(
  subscribe: Subscribe<T>,
  sink: Writable,
  options: IngestOptions,
): Promise<IngestReport> {
  const { limit, signal } = options;
  if (!Number.isInteger(limit) || limit < 1) {
    throw new Error("runIngest: limit must be a positive integer");
  }

  // Already-aborted must not subscribe at all: a listener on a fired signal
  // never runs, so this is the one case that would otherwise do nothing.
  if (signal?.aborted) {
    sink.destroy();
    throw abortError(signal.reason);
  }

  let received = 0;
  let written = 0;
  let parked = 0;

  // --- bounded queue: the promise returned from push IS the backpressure.
  const queue: T[] = [];
  const waiters: Array<{ resolve: () => void; reject: (e: Error) => void }> = [];
  let ended = false;
  let pushedNull = false;
  let wantsMore = false;

  const source = new Readable({
    objectMode: true,
    highWaterMark: limit,
    read() {
      wantsMore = true;
      deliver();
    },
  });

  function deliver(): void {
    while (wantsMore && queue.length > 0) {
      const item = queue.shift() as T;
      waiters.shift()?.resolve(); // exactly one producer released per item
      if (!source.push(item)) wantsMore = false;
    }
    if (ended && !pushedNull && queue.length === 0) {
      pushedNull = true;
      source.push(null);
    }
  }

  function enqueue(item: T): Promise<void> {
    received += 1;
    queue.push(item);
    deliver();
    if (queue.length < limit) return Promise.resolve();
    parked += 1;
    return new Promise<void>((resolve, reject) => waiters.push({ resolve, reject }));
  }

  function rejectWaiters(err: Error): void {
    for (const w of waiters.splice(0, waiters.length)) w.reject(err);
  }

  // Counting stage: `written` must mean "accepted by the sink", not "queued",
  // because an abort leaves queued items unwritten.
  const counter = new Transform({
    objectMode: true,
    transform(item, _encoding, callback) {
      written += 1;
      callback(null, item);
    },
  });

  const sub = subscribe({
    onItem: (item) => enqueue(item),
    onEnd: () => {
      ended = true;
      deliver();
    },
    onError: (err) => {
      ended = true;
      rejectWaiters(err);
      source.destroy(err);
    },
  });

  // One guarded helper called from every path: six exits, one unsubscribe.
  let stopped = false;
  const stop = (): void => {
    if (stopped) return;
    stopped = true;
    sub.unsubscribe();
  };

  try {
    // The signal goes on the pipeline so the rejection is an abort rather
    // than a sink error - the caller retries one and not the other.
    await pipeline(source, counter, sink, signal ? { signal } : {});
    return { received, written, parked };
  } catch (err) {
    const failure =
      (err as Error)?.name === "AbortError" || (err as Error)?.name === "TimeoutError"
        ? abortError(signal?.reason ?? err)
        : (err as Error);
    rejectWaiters(failure);
    if (!sink.destroyed) sink.destroy();
    throw failure;
  } finally {
    stop();
  }
}

