// v3na04_backpressure_pipeline / review1 - reference solution (author only, used by `dojo verify`).
import { once } from "node:events";
import { finished } from "node:stream/promises";
import type { Readable, Writable } from "node:stream";

export interface PumpOptions {
  end?: boolean;
}

export async function pump(
  source: Readable,
  destination: Writable,
  options: PumpOptions = {},
): Promise<void> {
  const shouldEnd = options.end ?? true;
  let lastWrite: Promise<void> | undefined;

  try {
    for await (const chunk of source) {
      // Capture the per-write callback as a promise: write() returning true
      // only means "buffered", not "processed".
      lastWrite = new Promise<void>((resolve, reject) => {
        const ok = destination.write(chunk, (err) => (err ? reject(err) : resolve()));
        if (!ok) {
          // Honour the contract. once() rejects if the sink dies while we
          // wait, instead of parking forever on a drain that never comes.
          void once(destination, "drain").catch(() => {});
        }
      });
      if (destination.writableNeedDrain) await once(destination, "drain");
    }
  } catch (err) {
    // Breaking out of `for await` already destroys the source; be explicit
    // for the case where the failure came from the destination.
    if (!source.destroyed) source.destroy();
    // Only destroy a destination we own. A shared sink has other writers who
    // did nothing wrong, which is the entire reason `end: false` exists.
    if (shouldEnd && !destination.destroyed) destination.destroy();
    throw err;
  }

  if (shouldEnd) {
    destination.end();
    await finished(destination);
    return;
  }

  // end: false - the strongest honest promise is "the sink has processed
  // every byte I gave it", which is the last write's callback, not a drain.
  await lastWrite;
}

// v3na05_fs_handles_atomic / ex1 - reference solution (author only, used by `dojo verify`).
import { open } from "node:fs/promises";

export async function readAt(
  path: string,
  offset: number,
  length: number,
): Promise<Buffer> {
  // Validate before touching the filesystem: a bad argument should not cost
  // an open, and the stack trace names the caller rather than fs internals.
  if (!Number.isInteger(offset) || offset < 0) {
    throw new Error(`readAt: offset must be a non-negative integer, got ${offset}`);
  }
  if (!Number.isInteger(length) || length < 0) {
    throw new Error(`readAt: length must be a non-negative integer, got ${length}`);
  }
  if (length === 0) return Buffer.alloc(0);

  const handle = await open(path, "r");
  try {
    const buffer = Buffer.alloc(length);
    // (buffer, offsetIntoBuffer, bytesToRead, positionInFile)
    const { bytesRead } = await handle.read(buffer, 0, length, offset);
    // Trim: Buffer.alloc zero-fills, so an unsliced short read hands back
    // trailing zeroes that a binary parser will happily accept as data.
    return buffer.subarray(0, bytesRead);
  } finally {
    // Every path, including a throwing read. A leaked handle is a leaked
    // descriptor that Node closes on GC, far too late to attribute.
    await handle.close();
  }
}

// v3na05_fs_handles_atomic / ex2 - reference solution (author only, used by `dojo verify`).
import { open, rename, unlink } from "node:fs/promises";
import type { FileHandle } from "node:fs/promises";
import { basename, dirname, join } from "node:path";
import { randomUUID } from "node:crypto";

export async function writeFileAtomic(
  path: string,
  data: Buffer | string,
): Promise<void> {
  // Same directory as the target: rename is only atomic within a filesystem,
  // and os.tmpdir() is very often a different one (EXDEV in the container,
  // works on the laptop).
  const tmp = join(dirname(path), `.${basename(path)}.${randomUUID()}.tmp`);

  let handle: FileHandle | undefined;
  try {
    handle = await open(tmp, "wx"); // O_EXCL: never clobber a stray temp file
    await handle.writeFile(data);
    // Durability before atomicity: some filesystems will persist the rename
    // before the data, leaving a correctly named file full of zeroes.
    await handle.sync();
    await handle.close();
    handle = undefined; // closed before the rename - required on Windows

    await rename(tmp, path);
  } catch (err) {
    await handle?.close().catch(() => {});
    // ENOENT is expected here: the failure may have been the create itself.
    await unlink(tmp).catch(() => {});
    throw err; // the original error, not a cleanup error
  }
}

