## Challenge — a rotating log writer

Edit `challenge/solution.ts`. Implement:

```ts
export interface RotatingWriterOptions {
  path: string;
  maxBytes: number;    // rotate once the current file would exceed this
  keep: number;        // how many rotated generations to retain
}

export interface RotatingWriter {
  write(line: string): Promise<void>;
  rotations(): number;
  close(): Promise<void>;
}

export function createRotatingWriter(
  options: RotatingWriterOptions,
): Promise<RotatingWriter>;
```

Append newline-terminated lines through a held `FileHandle`, rotating when the
file would exceed `maxBytes`.

Rotation, in order: close the current handle; unlink `path.{keep}` if it
exists; rename `path.{n}` to `path.{n+1}` for `n` from `keep - 1` down to `1`;
rename `path` to `path.1`; open a fresh `path` in append mode.

```ts
const w = await createRotatingWriter({ path: p, maxBytes: 20, keep: 2 });
await w.write("aaaaaaaaa");     // 10 bytes with the newline
await w.write("bbbbbbbbb");     // 20 bytes — still fits exactly
await w.write("ccccccccc");     // would be 30: rotate first
await w.close();
// p       contains "ccccccccc\n"
// p.1     contains "aaaaaaaaa\nbbbbbbbbb\n"
// p.3     does not exist
```

Required behaviour:

- **no line is ever lost or duplicated across a rotation** — the gate writes a
  thousand lines concurrently (without awaiting each one) through a writer with
  a tiny `maxBytes`, then reads every generation back and asserts the exact
  multiset of lines;
- concurrent `write` calls are serialised, so a rotation can never interleave
  with a write;
- the size is tracked by counting bytes written, not by calling `stat` — you
  are the only writer, and a `stat` per line is a syscall per line;
- an existing file is opened in append mode and its current size is the
  starting count;
- a line longer than `maxBytes` is written anyway, to a freshly rotated file,
  rather than looping forever;
- `close()` is idempotent and flushes.

```
uv run dojo test node v3na05_fs_handles_atomic challenge
```

references.solution.ts:
// v3na05_fs_handles_atomic / challenge - reference solution (author only, used by `dojo verify`).
import { open, rename, stat, unlink } from "node:fs/promises";
import type { FileHandle } from "node:fs/promises";

export interface RotatingWriterOptions {
  path: string;
  maxBytes: number;
  keep: number;
}

export interface RotatingWriter {
  write(line: string): Promise<void>;
  rotations(): number;
  close(): Promise<void>;
}

export async function createRotatingWriter(
  options: RotatingWriterOptions,
): Promise<RotatingWriter> {
  const { path, maxBytes, keep } = options;
  if (!Number.isInteger(maxBytes) || maxBytes < 1) {
    throw new Error("createRotatingWriter: maxBytes must be a positive integer");
  }
  if (!Number.isInteger(keep) || keep < 1) {
    throw new Error("createRotatingWriter: keep must be a positive integer");
  }

  let handle: FileHandle | undefined = await open(path, "a");
  // Start from the existing size, tracked by counting: a stat per line is a
  // syscall per line, and we are the only writer.
  let size = (await stat(path)).size;
  let rotations = 0;
  let closed = false;

  // Serialisation. Callers will not await every write, so without this a
  // rotation can interleave with an append and the line lands in the wrong
  // inode - or on a closed handle - with no error anywhere.
  let tail: Promise<void> = Promise.resolve();

  async function rotate(): Promise<void> {
    // Close FIRST: a FileHandle points at an inode, so writes after the
    // rename would still land in the archived file.
    await handle?.close();
    handle = undefined;

    await unlink(`${path}.${keep}`).catch(() => {});
    for (let n = keep - 1; n >= 1; n--) {
      // Downward, so generation n never overwrites generation n+1.
      await rename(`${path}.${n}`, `${path}.${n + 1}`).catch(() => {});
    }
    await rename(path, `${path}.1`).catch(() => {});

    handle = await open(path, "a");
    size = 0;
    rotations += 1;
  }

  async function doWrite(line: string): Promise<void> {
    if (closed) throw new Error("createRotatingWriter: write after close");
    const payload = Buffer.from(`${line}\n`, "utf8");

    // `size > 0` matters: a single line longer than maxBytes would otherwise
    // rotate before every write forever, producing `keep` empty files.
    if (size > 0 && size + payload.length > maxBytes) await rotate();

    await (handle as FileHandle).write(payload);
    size += payload.length;
  }

  return {
    write(line: string): Promise<void> {
      // Both handlers, so one failed write does not poison the chain and
      // reject every write after it with a stale error.
      tail = tail.then(
        () => doWrite(line),
        () => doWrite(line),
      );
      return tail;
    },

    rotations: () => rotations,

    async close(): Promise<void> {
      if (closed) return; // idempotent
      // Let queued writes finish before closing the handle under them.
      await tail.catch(() => {});
      closed = true;
      await handle?.close();
      handle = undefined;
    },
  };
}

// v3na05_fs_handles_atomic / review1 - reference solution (author only, used by `dojo verify`).
import { realpath } from "node:fs/promises";
import { isAbsolute, relative, resolve, sep } from "node:path";

function assertInside(root: string, target: string): string {
  // relative(), not startsWith(): a prefix test accepts "/data/uploads-evil"
  // for a root of "/data/uploads", because string prefixes do not respect
  // path boundaries. This is the Zip Slip / path-traversal class of bug.
  const rel = relative(root, target);
  const inside =
    rel === "" ||
    // ".." at the start means the target is above the root...
    (!rel.startsWith(`..${sep}`) &&
      rel !== ".." &&
      // ...and an absolute result means there is no relative path at all,
      // which on Windows is what you get across two drive letters.
      !isAbsolute(rel));

  if (!inside) {
    throw new Error(`resolveWithin: ${target} is outside ${root}`);
  }
  return target;
}

export function resolveWithin(root: string, userPath: string): string {
  const absRoot = resolve(root);
  // resolve() normalises "." and ".." and makes an absolute userPath win,
  // which is why the containment check has to come after it, not before.
  return assertInside(absRoot, resolve(absRoot, userPath));
}

export async function realResolveWithin(
  root: string,
  userPath: string,
): Promise<string> {
  // Lexical check first: cheap, and it rejects the obvious attacks before any
  // I/O happens.
  const lexical = resolveWithin(root, userPath);

  // Then the real one. A path lexically inside the root can still be a
  // symlink pointing anywhere; realpath resolves both sides so the comparison
  // is between two physical locations. Requires the file to exist - ENOENT
  // propagates, which is why this cannot be the only check.
  const realRoot = await realpath(resolve(root));
  const realTarget = await realpath(lexical);
  return assertInside(realRoot, realTarget);
}

