// v3na06_compression_crypto / ex1 - reference solution (author only, used by `dojo verify`).
import { PassThrough } from "node:stream";
import { pipeline } from "node:stream/promises";
import { createGzip } from "node:zlib";
import type { Readable } from "node:stream";

export interface CompressionResult {
  data: Buffer;
  inputBytes: number;
  outputBytes: number;
  ratio: number;
}

export function compress(
  source: Readable,
  level = 6,
): Promise<CompressionResult> {
  if (!Number.isInteger(level) || level < 0 || level > 9) {
    throw new Error(`compress: level must be an integer 0-9, got ${level}`);
  }

  let inputBytes = 0;
  // A transparent counter on the input side: the ratio needs both numbers,
  // and only a stage before the compressor can see the uncompressed size.
  const counter = new PassThrough();
  counter.on("data", (chunk: Buffer) => {
    inputBytes += chunk.length;
  });

  return pipeline(
    source,
    counter,
    createGzip({ level }),
    // pipeline's async-function sink form (Node 16+): the promise resolves
    // with whatever this returns, so no Writable is needed.
    async function (compressed) {
      const chunks: Buffer[] = [];
      for await (const chunk of compressed) chunks.push(chunk as Buffer);
      const data = Buffer.concat(chunks);
      return {
        data,
        inputBytes,
        outputBytes: data.length,
        // 0/0 is NaN, which propagates silently into every downstream
        // calculation. Pick a value on purpose.
        ratio: inputBytes === 0 ? 1 : data.length / inputBytes,
      };
    },
  );
}

// v3na06_compression_crypto / ex2 - reference solution (author only, used by `dojo verify`).
import { pipeline } from "node:stream/promises";
import { createGunzip, createInflate, createInflateRaw } from "node:zlib";
import type { Readable, Transform } from "node:stream";
import { once } from "node:events";

export type Encoding = "gzip" | "zlib" | "raw-deflate";

export function detectEncoding(prefix: Buffer): Encoding {
  if (prefix.length >= 2 && prefix[0] === 0x1f && prefix[1] === 0x8b) return "gzip";
  if (prefix.length >= 2) {
    const cmf = prefix[0];
    const flg = prefix[1];
    // RFC 1950: low nibble 8 is DEFLATE, and the two header bytes read as a
    // big-endian uint16 must be a multiple of 31.
    if ((cmf & 0x0f) === 8 && ((cmf << 8) + flg) % 31 === 0) return "zlib";
  }
  // Raw deflate has no header at all, so it is what is left over.
  return "raw-deflate";
}

const factories: Record<Encoding, () => Transform> = {
  gzip: createGunzip,
  zlib: createInflate,
  "raw-deflate": createInflateRaw,
};

export async function decompressAuto(source: Readable): Promise<Buffer> {
  const prefix = await readPrefix(source, 2);
  const encoding = detectEncoding(prefix);

  // Put the bytes BACK. The magic is part of the format, not a marker to
  // strip: gunzip reads the method, flags, mtime, XFL and OS bytes after it.
  if (prefix.length > 0 && !source.readableEnded) source.unshift(prefix);

  return pipeline(source, factories[encoding](), async function (out) {
    const chunks: Buffer[] = [];
    for await (const chunk of out) chunks.push(chunk as Buffer);
    return Buffer.concat(chunks);
  });
}

async function readPrefix(source: Readable, n: number): Promise<Buffer> {
  for (;;) {
    const exact = source.read(n) as Buffer | null;
    if (exact !== null) return exact;
    if (source.readableEnded) {
      // Short stream: take whatever there is; it cannot be unshifted.
      return (source.read() as Buffer | null) ?? Buffer.alloc(0);
    }
    await once(source, "readable");
  }
}

