// v3na06_compression_crypto / ex3 - reference solution (author only, used by `dojo verify`).
import { Transform } from "node:stream";
import { pipeline } from "node:stream/promises";
import { createGunzip } from "node:zlib";
import type { Readable } from "node:stream";

export function gunzipLimited(
  source: Readable,
  maxBytes: number,
): Promise<Buffer> {
  if (!Number.isInteger(maxBytes) || maxBytes < 1) {
    throw new Error(`gunzipLimited: maxBytes must be a positive integer`);
  }

  let total = 0;
  // The limit lives AFTER the decompressor and fires per chunk. Limiting the
  // input is meaningless (the ratio is the attacker's choice) and checking the
  // total at the end is too late - the memory is already allocated.
  const limiter = new Transform({
    transform(chunk: Buffer, _encoding, callback) {
      total += chunk.length;
      if (total > maxBytes) {
        // callback(err) destroys this stage; pipeline destroys the gunzip
        // stage in turn, so decompression stops rather than running on.
        callback(
          new Error(`gunzipLimited: decompressed output exceeded ${maxBytes} bytes`),
        );
        return;
      }
      callback(null, chunk);
    },
  });

  return pipeline(source, createGunzip(), limiter, async function (out) {
    const chunks: Buffer[] = [];
    for await (const chunk of out) chunks.push(chunk as Buffer);
    return Buffer.concat(chunks);
  });
}

