// v3na06_compression_crypto / ex4 - reference solution (author only, used by `dojo verify`).
import { Transform } from "node:stream";
import { createHash } from "node:crypto";

export interface HashingStream {
  stream: Transform;
  digest(): Buffer;
  bytes(): number;
}

export function createHashingPassThrough(algorithm: string): HashingStream {
  // Constructing here means an unknown algorithm throws from the factory,
  // with the caller's stack, rather than from the first write.
  const hash = createHash(algorithm);
  let finalDigest: Buffer | undefined;
  let bytes = 0;

  const stream = new Transform({
    transform(chunk: Buffer, _encoding, callback) {
      hash.update(chunk);
      bytes += chunk.length;
      // Same chunk out, immediately: the stage must be transparent, including
      // in its chunk boundaries.
      callback(null, chunk);
    },

    flush(callback) {
      // digest() on the hash object is one-shot, so finalise exactly once.
      finalDigest = hash.digest();
      callback();
    },
  });

  return {
    stream,
    digest(): Buffer {
      // Throwing beats returning a prefix hash: a wrong answer that looks
      // like a hash invites someone to "fix" the comparison instead.
      if (!finalDigest) {
        throw new Error("createHashingPassThrough: stream is not finished");
      }
      // A copy: a caller who mutates the returned buffer would corrupt what
      // the next caller compares.
      return Buffer.from(finalDigest);
    },
    bytes: () => bytes,
  };
}

// v3na06_compression_crypto / ex5 - reference solution (author only, used by `dojo verify`).
import { createHmac, timingSafeEqual } from "node:crypto";
import type { Readable } from "node:stream";

function safeEquals(a: Buffer, b: Buffer): boolean {
  // timingSafeEqual throws on unequal lengths. Branching on length leaks
  // nothing: MAC lengths are public constants.
  if (a.length !== b.length) return false;
  return timingSafeEqual(a, b);
}

export async function verifyHmac(
  source: Readable,
  key: Buffer,
  expected: Buffer,
  algorithm = "sha256",
): Promise<Buffer> {
  const hmac = createHmac(algorithm, key);
  const chunks: Buffer[] = [];

  // One pass: update the MAC and collect at the same time. The source may be
  // a socket, which cannot be read twice.
  for await (const chunk of source) {
    const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk as string);
    hmac.update(buf);
    chunks.push(buf);
  }

  if (!safeEquals(hmac.digest(), expected)) {
    // No detail: including the computed MAC would hand an attacker a valid
    // signature for a body they chose, which is exactly what the key protects.
    throw new Error("verifyHmac: invalid signature");
  }

  return Buffer.concat(chunks);
}

// v3na06_compression_crypto / ex6 - reference solution (author only, used by `dojo verify`).
import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

const IV_BYTES = 12; // 96 bits: used directly as the GCM counter prefix
const TAG_BYTES = 16;
const KEY_BYTES = 32; // AES-256

export function seal(key: Buffer, plaintext: Buffer): Buffer {
  if (key.length !== KEY_BYTES) {
    throw new Error(`seal: key must be ${KEY_BYTES} bytes, got ${key.length}`);
  }

  // A fresh IV per message, from the CSPRNG. Reuse under GCM leaks the XOR of
  // the plaintexts AND the authentication subkey, which allows forgery.
  const iv = randomBytes(IV_BYTES);
  const cipher = createCipheriv("aes-256-gcm", key, iv);
  const body = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  // The tag only exists after final().
  const tag = cipher.getAuthTag();

  // IV first (a reader needs it to start), tag last (a writer has it only at
  // the end) - the only layout that lets both sides stream.
  return Buffer.concat([iv, body, tag]);
}

export function unseal(key: Buffer, sealed: Buffer): Buffer {
  if (key.length !== KEY_BYTES) {
    throw new Error(`unseal: key must be ${KEY_BYTES} bytes, got ${key.length}`);
  }
  if (sealed.length < IV_BYTES + TAG_BYTES) {
    throw new Error("unseal: sealed value is too short");
  }

  const iv = sealed.subarray(0, IV_BYTES);
  const body = sealed.subarray(IV_BYTES, sealed.length - TAG_BYTES);
  const tag = sealed.subarray(sealed.length - TAG_BYTES);

  const decipher = createDecipheriv("aes-256-gcm", key, iv);
  decipher.setAuthTag(tag); // BEFORE final(), or it is not checked at all

  try {
    // final() is the verification: it recomputes the tag and compares in
    // constant time. Catching and continuing would mean accepting whatever
    // the attacker sent.
    return Buffer.concat([decipher.update(body), decipher.final()]);
  } catch (err) {
    // One error for every kind of invalid input. Distinguishable errors let an
    // attacker search each part of a forgery independently - the padding
    // oracle lesson, in miniature.
    throw new Error("unseal: authentication failed", { cause: err });
  }
}

// v3na06_compression_crypto / ex7 - reference solution (author only, used by `dojo verify`).
import { constants, createGzip } from "node:zlib";
import type { Transform } from "node:stream";

export function createLiveGzip(): Transform {
  // Z_SYNC_FLUSH ends the current deflate block after every write and emits an
  // empty stored block (00 00 ff ff) as a marker, so bytes reach the consumer
  // immediately. The cost is ~5 bytes per flush plus the lost cross-block
  // matches - real, and worth it only when a human is watching.
  return createGzip({ flush: constants.Z_SYNC_FLUSH });
}

export async function collectOutputPerWrite(
  gzip: Transform,
  lines: readonly string[],
): Promise<number[]> {
  let produced = 0;
  gzip.on("data", (chunk: Buffer) => {
    produced += chunk.length;
  });

  const deltas: number[] = [];
  for (const line of lines) {
    const before = produced;
    // The per-write callback is the honest synchronisation point: it fires
    // when this chunk has been processed. A setImmediate would pass locally
    // and flake under load.
    await new Promise<void>((resolve, reject) => {
      gzip.write(line, (err) => (err ? reject(err) : resolve()));
    });
    deltas.push(produced - before);
  }

  return deltas;
}

