// v3na06_compression_crypto / ex8 - reference solution (author only, used by `dojo verify`).
import { deflateRawSync, inflateRawSync } from "node:zlib";

export interface DictionaryCodec {
  encode(message: Buffer): Buffer;
  decode(packed: Buffer): Buffer;
}

export function createDictionaryCodec(dictionary: Buffer): DictionaryCodec {
  // Only the last 32 KiB is used: the dictionary primes the sliding window,
  // and the window is 32 KiB. Anything earlier is simply never reachable.
  return {
    // Raw deflate on both sides. The zlib format would carry an Adler-32 of
    // the dictionary in its header and reject a mismatch cleanly; raw has no
    // header at all, so a mismatched dictionary corrupts instead of erroring.
    encode: (message: Buffer): Buffer => deflateRawSync(message, { dictionary }),

    // Stateless per message: no shared compression context, so messages can
    // be reordered or redelivered - and no CRIME-style cross-message leak.
    decode: (packed: Buffer): Buffer => inflateRawSync(packed, { dictionary }),
  };
}

