// v3na06_compression_crypto / challenge - reference solution (author only, used by `dojo verify`).
import { createCipheriv, createDecipheriv, randomBytes, scrypt } from "node:crypto";
import { gzip, gunzip } from "node:zlib";
import { promisify } from "node:util";

const gzipAsync = promisify(gzip);
const gunzipAsync = promisify(gunzip);
const scryptAsync = promisify(scrypt) as (
  password: string,
  salt: Buffer,
  keylen: number,
) => Promise<Buffer>;

export interface SealOptions {
  password: string;
  maxPlaintextBytes?: number;
}

const MAGIC = Buffer.from("IPSK", "latin1");
const VERSION = 1;
const HEADER_BYTES = 5; // magic + version, authenticated as AAD
const SALT_BYTES = 16;
const IV_BYTES = 12;
const TAG_BYTES = 16;
const PREFIX_BYTES = HEADER_BYTES + SALT_BYTES + IV_BYTES;
const DEFAULT_MAX = 64 * 1024 * 1024;

export async function sealBuffer(
  data: Buffer,
  options: SealOptions,
): Promise<Buffer> {
  const salt = randomBytes(SALT_BYTES);
  const iv = randomBytes(IV_BYTES);
  // scrypt, not a hash of the password: a password is not a key. Async
  // because the default cost parameters block for 50-100ms.
  const key = await scryptAsync(options.password, salt, 32);

  // Compress FIRST. Ciphertext is indistinguishable from random and does not
  // compress, so the other order is full CPU cost for nothing.
  const compressed = await gzipAsync(data);

  const header = Buffer.concat([MAGIC, Buffer.from([VERSION])]);
  const cipher = createCipheriv("aes-256-gcm", key, iv);
  // The header is not encrypted but IS authenticated, so the version byte
  // cannot be downgraded to reach a legacy parsing path.
  cipher.setAAD(header);
  const body = Buffer.concat([cipher.update(compressed), cipher.final()]);

  return Buffer.concat([header, salt, iv, body, cipher.getAuthTag()]);
}

export async function openBuffer(
  container: Buffer,
  options: SealOptions,
): Promise<Buffer> {
  if (container.length < PREFIX_BYTES + TAG_BYTES) {
    throw new Error("openBuffer: cannot open container (too short)");
  }
  // Magic and version carry no secret, so specific errors here leak nothing
  // and are far more useful than a generic one.
  if (!container.subarray(0, 4).equals(MAGIC)) {
    throw new Error("openBuffer: not an IPSK container");
  }
  const version = container[4];
  if (version !== VERSION) {
    throw new Error(`openBuffer: unsupported container version ${version}`);
  }

  const header = container.subarray(0, HEADER_BYTES);
  const salt = container.subarray(HEADER_BYTES, HEADER_BYTES + SALT_BYTES);
  const iv = container.subarray(HEADER_BYTES + SALT_BYTES, PREFIX_BYTES);
  const body = container.subarray(PREFIX_BYTES, container.length - TAG_BYTES);
  const tag = container.subarray(container.length - TAG_BYTES);

  const key = await scryptAsync(options.password, salt, 32);
  const decipher = createDecipheriv("aes-256-gcm", key, iv);
  decipher.setAAD(header);
  decipher.setAuthTag(tag); // before final(), or the tag is never checked

  let compressed: Buffer;
  try {
    compressed = Buffer.concat([decipher.update(body), decipher.final()]);
  } catch (err) {
    // One message for a wrong password and for any tampering: distinguishable
    // errors let an attacker search each part of a forgery independently.
    throw new Error("openBuffer: cannot open container", { cause: err });
  }

  const limit = options.maxPlaintextBytes ?? DEFAULT_MAX;
  try {
    // The limit sits AFTER decryption. Authentication proves who wrote the
    // container, never that its compression ratio is sane - a legitimate
    // holder of the password can seal a bomb.
    return await gunzipAsync(compressed, { maxOutputLength: limit });
  } catch (err) {
    throw new Error(
      `openBuffer: decompressed output exceeded ${limit} bytes or was corrupt`,
      { cause: err },
    );
  }
}

