// v3na06_compression_crypto / review1 - reference solution (author only, used by `dojo verify`).
import { createHash, timingSafeEqual } from "node:crypto";
import { createWriteStream } from "node:fs";
import { rename, unlink } from "node:fs/promises";
import { basename, dirname, join } from "node:path";
import { randomUUID } from "node:crypto";
import { Transform } from "node:stream";
import { pipeline } from "node:stream/promises";
import type { Readable } from "node:stream";

export interface ReceiveOptions {
  expectedSha256: Buffer;
  maxBytes: number;
}

export async function receiveVerified(
  source: Readable,
  destinationPath: string,
  options: ReceiveOptions,
): Promise<number> {
  const { expectedSha256, maxBytes } = options;
  if (!Number.isInteger(maxBytes) || maxBytes < 1) {
    throw new Error("receiveVerified: maxBytes must be a positive integer");
  }

  // Same directory: rename is only atomic within a filesystem.
  const tmp = join(
    dirname(destinationPath),
    `.${basename(destinationPath)}.${randomUUID()}.tmp`,
  );

  const hash = createHash("sha256");
  let bytes = 0;

  const meter = new Transform({
    transform(chunk: Buffer, _encoding, callback) {
      bytes += chunk.length;
      // A resource control, distinct from the integrity control below: the
      // digest would also catch a wrong-sized file, but only after writing
      // all of it, by which time the disk is full.
      if (bytes > maxBytes) {
        callback(new Error(`receiveVerified: input exceeded ${maxBytes} bytes`));
        return;
      }
      hash.update(chunk);
      callback(null, chunk);
    },
  });

  try {
    await pipeline(source, meter, createWriteStream(tmp));

    const actual = hash.digest();
    // Length guard first: timingSafeEqual throws on a mismatch, and digest
    // lengths are public.
    if (
      actual.length !== expectedSha256.length ||
      !timingSafeEqual(actual, expectedSha256)
    ) {
      throw new Error("receiveVerified: checksum mismatch");
    }

    // Only now does the file get its real name. The naive order - write,
    // hash, unlink on mismatch - leaves a corrupt file under the real name
    // for as long as the verification takes.
    await rename(tmp, destinationPath);
    return bytes;
  } catch (err) {
    // Swallowed: a cleanup failure must not replace the real error with an
    // ENOENT about a temp file the caller never heard of.
    await unlink(tmp).catch(() => {});
    throw err;
  }
}
